import subprocess
import shlex

def safe_run(command_str: str) -> str:
    args = shlex.split(command_str)
    try:
        result = subprocess.run(args, shell=False, capture_output=True, timeout=10)
        return result.stdout.decode('utf-8')
    except subprocess.TimeoutExpired:
        raise RuntimeError('Command timed out')

